import{_ as e,o as t,c as o,aa as i}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/cs/diary/siotech_nastaveni.png",n="/buildary-help-preview/media/cs/diary/siotech_teploty.png",v=JSON.parse('{"title":"Čidla a odkaz na stavbu","description":"","frontmatter":{"title":"Čidla a odkaz na stavbu","wiki":"cs:diary:sensors"},"headers":[],"relativePath":"diary/sensors.md","filePath":"diary/sensors.md","lastUpdated":1794209661000}'),l={name:"diary/sensors.md"};function d(r,a,p,u,c,k){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="cidla-a-odkaz-na-stavbu" tabindex="-1">Čidla a odkaz na stavbu <a class="header-anchor" href="#cidla-a-odkaz-na-stavbu" aria-label="Permalink to &quot;Čidla a odkaz na stavbu&quot;">​</a></h1><p>Deník umí načítat teplotu z digitálního čidla na stavbě. A pokud máte vlastní informační systém, můžete z něj otevírat Buildary rovnou na konkrétní stavbě.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/napojeni">Napojit docházku nebo čidla</a> v Akademii.</p><h2 id="digitalni-cidla" tabindex="-1">Digitální čidla <a class="header-anchor" href="#digitalni-cidla" aria-label="Permalink to &quot;Digitální čidla&quot;">​</a></h2><p>Buildary lze napojit na samostatná digitální čidla a měřicí přístroje. Podmínkou je, aby naměřená data byla dostupná přes internet a jejich správce umožnil Buildary k nim přístup – nejlépe webovou službou. Máte-li tip na zařízení, které by stálo za napojení, napište nám na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p><h3 id="teplotni-cidlo-siotech" tabindex="-1">Teplotní čidlo Siotech <a class="header-anchor" href="#teplotni-cidlo-siotech" aria-label="Permalink to &quot;Teplotní čidlo Siotech&quot;">​</a></h3><p>Čidlo Siotech umístíte kamkoli na stavbu a ono každých 10 minut odesílá aktuální teplotu na server Siotech. Tam máte celý průběh teplot za sledované období v číslech i v grafu. Do deníku se z něj načte teplota jen v hodinách, kdy se v deníku zapisuje počasí – práce s deníkem se tedy nemění.</p><p>Zapnutí: v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> na záložce <strong>Počasí</strong> vyplňte do pole <strong>Siotech čidlo</strong> ID vašeho čidla.</p><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="Záložka Počasí v Nastavení deníku s vyplněným polem Siotech čidlo" loading="lazy"></figure><p>Jak se to projeví v deníku:</p><ul><li>Teplota se načítá z čidla a v deníku ji ručně změnit nejde. Ostatní údaje o počasí se zapisují jako obvykle.</li><li>Do poznámky k počasí se zapíše, že teplota pochází z čidla, jeho ID a časy měření.</li><li>Teplotu nelze vyplnit dopředu, jen zpětně – až je naměřená.</li></ul><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Sekce Počasí s poznámkou, že údaje o teplotě byly získány z čidla" loading="lazy"></figure><div class="tip custom-block"><p class="custom-block-title">Vyzkoušet čidlo</p><p>Pokud byste čidlo rádi vyzkoušeli, napište nám na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p></div><h2 id="odkaz-na-stavbu-z-jineho-systemu" tabindex="-1">Odkaz na stavbu z jiného systému <a class="header-anchor" href="#odkaz-na-stavbu-z-jineho-systemu" aria-label="Permalink to &quot;Odkaz na stavbu z jiného systému&quot;">​</a></h2><p>Pokud chcete otevírat Buildary ze svého informačního systému rovnou na konkrétní stavbě, vyplňte u stavby <strong>Číslo stavby dle stavebníka</strong> – číslo nebo kód, pod kterým stavbu vedete ve svém systému. Pole je v levém panelu pod názvem stavby, upravíte ho ikonou tužky.</p><p>Váš systém pak použije odkaz, kde místo <code>XXX</code> doplní číslo stavby dle stavebníka:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.buildary.online/project/employer-number?employerNumber=XXX</span></span></code></pre></div>',17)])])}const h=e(l,[["render",d]]);export{v as __pageData,h as default};
